import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
export type Language = "es" | "ca" | "en";
export function translate(language: Language, text: string): string {
  const connectionError = text.match(/^Error de conexión \((\d+)\)\.$/);
  if (connectionError && language === "en") return `Connection error (${connectionError[1]}).`;
  if (connectionError && language === "ca") return `Error de connexió (${connectionError[1]}).`;
  if (language === "en") {
    const late = text.match(/^≈ (\d+) min de retraso$/);
    if (late) return `≈ ${late[1]} min delayed`;
    const early = text.match(/^≈ (\d+) min adelantado$/);
    if (early) return `≈ ${early[1]} min early`;
  }
  if (language === "ca") {
    const late = text.match(/^≈ (\d+) min de retraso$/);
    if (late) return `≈ ${late[1]} min de retard`;
    const early = text.match(/^≈ (\d+) min adelantado$/);
    if (early) return `≈ ${early[1]} min d’avançament`;
  }
  return translations[language][text] ?? text;
}
